:root{--bg:#0b1220;--panel:#111c30;--line:#22314f;--ink:#e8eef7;--muted:#93a5c4;--accent:#2dd4bf;--amber:#f5b942;--red:#f26d6d;--green:#4ade80}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
header,section,footer,main{max-width:1080px;margin:0 auto;padding:16px 20px}
h1{margin:8px 0 0;font-size:30px;letter-spacing:.2px}
h2{margin:0 0 8px;font-size:19px;color:var(--accent)}
.sub{color:var(--muted);margin:6px 0}
.meta{color:var(--amber);margin:6px 0}
#model{background:var(--panel);border:1px solid var(--line);border-radius:10px}
#model p{margin:6px 0;color:#c6d2e6}
#controls{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end}
