#controls label.check{flex-direction:row;align-items:center;gap:6px;padding-bottom:8px;color:var(--ink)}
input,select{background:#0e1830;border:1px solid var(--line);color:var(--ink);border-radius:6px;padding:7px 9px;font:inherit}
input:focus,select:focus{outline:2px solid var(--accent)}
#count{width:100%;margin:0;color:var(--muted)}
table{width:100%;border-collapse:collapse;background:var(--panel);border-radius:10px;overflow:hidden}
th,td{padding:8px 10px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}
thead th{background:#16233d;color:var(--accent);font-size:12px;text-transform:uppercase;letter-spacing:.4px;position:sticky;top:0}
tbody tr{cursor:pointer}
