td .up{color:var(--green)}td .down{color:var(--red)}
.implied{color:var(--amber);font-weight:700}
#detail-body{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:16px}
#detail-body h3{margin:0 0 4px;font-size:22px}
